  const ring = new THREE.Mesh(new THREE.RingGeometry(5.9, 5.94, 128), new THREE.MeshBasicMaterial({ color: 0x3a3540, side: THREE.DoubleSide })); ring.rotation.x = -Math.PI / 2; ring.position.y = 0.01; scene.add(ring);

  const U = { uSel: { value: -1 }, uPulse: { value: 0 }, uSelColor: { value: new THREE.Color(0xffa45c) } };
  const boneMat = new THREE.MeshPhysicalMaterial({ color: 0xe8d8bb, roughness: 0.62, clearcoat: 0.15, clearcoatRoughness: 0.6, sheen: 0.35, sheenColor: new THREE.Color(0xfff0d8), envMapIntensity: 0.65, side: THREE.DoubleSide, shadowSide: THREE.FrontSide });
